const input = $input.first().json || {};
const exteriorImages = Array.isArray(input.exteriorImages) ? input.exteriorImages : [];
const interiorImages = Array.isArray(input.interiorImages) ? input.interiorImages : [];
const groupName = `二手车图片组_${Date.now()}`;
const vehicleId = `car_${Date.now()}`;
const feishuAppId = input.feishu_app_id || '';
const feishuId = input.feishu_id || '';
const items = [];

if (!feishuAppId) {
  throw new Error('feishu_app_id is required for Feishu upload');
}

if (!feishuId) {
  throw new Error('feishu_id is required for Create Bitable Record');
}

exteriorImages.forEach((item, index) => {
  const url = item.imageUrl || '';
  if (!url) return;
  items.push({
    json: {
      submissionId: input.submissionId,
      groupName,
      vehicleId,
      feishu_app_id: feishuAppId,
      feishu_id: feishuId,
      category: '外观图',
      order: index + 1,
      sourceUrl: url,
      fileName: `exterior_${index + 1}.jpg`
    }
  });
});

interiorImages.forEach((item, index) => {
  const url = item.imageUrl || '';
  if (!url) return;
  items.push({
    json: {
      submissionId: input.submissionId,
      groupName,
      vehicleId,
      feishu_app_id: feishuAppId,
      feishu_id: feishuId,
      category: '内饰图',
      order: index + 1,
      sourceUrl: url,
      fileName: `interior_${index + 1}.jpg`
    }
  });
});

return items;

const uploadItem = $('Loop Upload Items').item.json;
const uploadResp = $json || {};
const fileToken = uploadResp.data?.file_token || uploadResp.file_token || '';
const errorMessage = uploadResp.error?.message || uploadResp.message || uploadResp.error || '';

return [{
  json: {
    submissionId: uploadItem.submissionId,
    groupName: uploadItem.groupName,
    vehicleId: uploadItem.vehicleId,
    feishu_app_id: uploadItem.feishu_app_id,
    feishu_id: uploadItem.feishu_id,
    category: uploadItem.category,
    order: uploadItem.order,
    sourceUrl: uploadItem.sourceUrl,
    fileName: uploadItem.fileName,
    fileToken,
    uploadStatus: fileToken ? 'success' : 'failed',
    uploadError: fileToken ? null : (String(errorMessage || 'Feishu upload returned no file_token after retries'))
  }
}];

const items = $input.all();
const result = {
  submissionId: items[0]?.json?.submissionId || '',
  groupName: items[0]?.json?.groupName || `二手车图片组_${Date.now()}`,
  vehicleId: items[0]?.json?.vehicleId || `car_${Date.now()}`,
  feishu_app_id: items[0]?.json?.feishu_app_id || '',
  feishu_id: items[0]?.json?.feishu_id || '',
  exteriorAttachments: [],
  interiorAttachments: [],
  uploadFailures: []
};

for (const item of items) {
  const token = item.json.fileToken;

  if (!token) {
    result.uploadFailures.push({
      category: item.json.category || '',
      order: item.json.order || null,
      fileName: item.json.fileName || '',
      sourceUrl: item.json.sourceUrl || '',
      error: item.json.uploadError || 'Feishu upload failed after retries'
    });
    continue;
  }

  const attachment = { file_token: token };

  if (item.json.category === '外观图') {
    result.exteriorAttachments.push(attachment);
  } else if (item.json.category === '内饰图') {
    result.interiorAttachments.push(attachment);
  }
}

result.uploadSuccessCount = result.exteriorAttachments.length + result.interiorAttachments.length;
result.uploadFailedCount = result.uploadFailures.length;

return [{ json: result }];

