const recordResp = $json || {};
const finalAssets = $('Build Final Assets').first().json;
const uploadSummary = $('Collect Attachments').first().json;
const submissionId = finalAssets.submissionId;

return [{
  json: {
    ok: true,
    accepted: true,
    finalized: true,
    submissionId,
    totalExterior: finalAssets.totalExterior,
    totalInterior: finalAssets.totalInterior,
    successCount: finalAssets.successCount || 0,
    failedCount: finalAssets.failedCount || 0,
    failedTasks: finalAssets.failedTasks || [],
    uploadSuccessCount: uploadSummary.uploadSuccessCount || 0,
    uploadFailedCount: uploadSummary.uploadFailedCount || 0,
    uploadFailures: uploadSummary.uploadFailures || [],
    recordResponse: recordResp
  }
}];

return [{
  json: {
    ok: true,
    accepted: true,
    finalized: false,
    submissionId: $json.submissionId || null,
    taskId: $json.taskId || null,
    state: $json.state || null,
    resolvedCount: $json.resolvedCount || 0,
    expectedTasks: $json.expectedTasks || 0,
    message: $json.reason === 'task_not_found' ? 'callback accepted but task was not found in middle-platform state store' : 'callback accepted, waiting for remaining tasks'
  }
}];
